  if(message==WM_GETMINMAXINFO){auto limits=reinterpret_cast<MINMAXINFO*>(lp);limits->ptMinTrackSize={self->px(540),self->px(400)};return 0;}if(message==WM_CLOSE){DestroyWindow(window);return 0;}if(message==WM_DESTROY){KillTimer(window,1);self->closed=true;return 0;}return DefWindowProcW(window,message,wp,lp);
